import React from "react";
import { useNavigate } from "react-router-dom";
import { motion } from "framer-motion";

const Home = () => {
  const navigate = useNavigate();

  return (
    <div className="relative flex flex-col items-center justify-center min-h-screen bg-gradient-to-br from-blue-900 via-blue-800 to-blue-700 text-white overflow-hidden">
      {/* Background animation circles */}
      <motion.div
        className="absolute w-96 h-96 bg-blue-500 rounded-full blur-3xl opacity-30 top-10 left-10"
        animate={{ y: [0, 20, 0] }}
        transition={{ duration: 6, repeat: Infinity }}
      />
      <motion.div
        className="absolute w-72 h-72 bg-indigo-400 rounded-full blur-3xl opacity-25 bottom-10 right-10"
        animate={{ y: [0, -20, 0] }}
        transition={{ duration: 8, repeat: Infinity }}
      />

      {/* Main content */}
      <motion.div
        className="text-center z-10 px-4"
        initial={{ opacity: 0, y: 50 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 1 }}
      >
        <h1 className="text-5xl md:text-6xl font-bold mb-4 tracking-tight">
          AI Interview Coach
        </h1>
        <p className="text-lg md:text-xl text-gray-200 max-w-xl mx-auto mb-8">
          Master your interviews with AI-powered insights, feedback, and personalized coaching.
        </p>

        <div className="flex flex-col md:flex-row gap-4 justify-center">
          <button
            onClick={() => navigate("/login")}
            className="bg-white text-blue-800 px-8 py-3 rounded-full text-lg font-semibold hover:bg-gray-200 transition-all"
          >
            Login
          </button>
          <button
            onClick={() => navigate("/signup")}
            className="bg-blue-500 text-white px-8 py-3 rounded-full text-lg font-semibold hover:bg-blue-600 transition-all"
          >
            Sign Up
          </button>
        </div>
      </motion.div>
    </div>
  );
};

export default Home;
